INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (427874, 16431, 'The Economic Times', 'en', 'Sebi plans bigger institutional role in public offers by small firms, sources say', 'https://economictimes.indiatimes.com/markets/stocks/news/sebi-plans-bigger-institutional-role-in-public-offers-by-small-firms-sources-say/articleshow/133596132.cms', 'India''s market regulator is considering new rules for small business public offerings. These potential changes include quotas for institutional investors ahead of share sales. The regulator may also raise listing size limits and profit requirements for these firms. These proposed adjustments follow concerns about fund diversion and high fees. Such moves aim to enhance governance and investor protection in the segment.', 'https://img.etimg.com/photo/msid-133596132,imgsize-87218.cms', '2026-08-28T17:02:10+00:00', '2026-08-29T00:04:38.841886'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
