INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422716, 16440, 'France 24', 'en', 'Serbian war criminal Mladic to be buried with ''state honours''', 'https://www.france24.com/en/serbian-war-criminal-mladic-to-be-buried-with-state-honours', 'Convicted genocidaire Ratko Mladić has died at the age of 84 in a UN prison in The Hague, where he was serving a life sentence. He was found guilty of leading the siege of Sarajevo and orchestrating the 1995 Srebrenica massacre, in which more than 8,000 Bosniak men and boys were murdered. His planned burial with national honours has sparked sharp divisions in Serbia.', 'https://s.france24.com/media/display/0f3cb8f8-a2cc-11f1-b591-005056bf30b7/w:1024/p:16x9/EN-20260828-121120-121329-CS.jpg', '2026-08-28T11:40:26+00:00', '2026-08-28T12:49:23.775115'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422731, 16440, 'France 24', 'en', 'Serbian war criminal Ratko Mladic to be buried with ''state honours''', 'https://www.france24.com/en/europe/20260828-serbian-war-criminal-ratko-mladic-to-be-buried-with-state-honours', 'Former Bosnian Serb military leader Ratko Mladic, known as the “Butcher of Bosnia" for his role in the 1995 Srebrenica massacre, will be given a funeral with “military and state honours”, Serbian Justice Minister Nenad Vujic said Friday. Mladic died Thursday in The Hague where he was serving a life sentence for genocide, war crimes, and crimes against humanity.', 'https://s.france24.com/media/display/caf629f0-c864-11eb-8f0e-005056bff430/w:1024/p:16x9/000_9BM6UK.jpg', '2026-08-28T08:51:50+00:00', '2026-08-28T12:49:23.946876'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
