INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422545, 16443, 'BBC News', 'en', 'World''s youngest reigning traditional monarch dies aged 34', 'https://www.bbc.co.uk/news/articles/c0j38d9v40po', 'King Oyo ascended to the throne of Uganda''s Tooro kingdom when he was just three years old.', 'https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/0f05/live/e8034d20-a2ca-11f1-aed2-8d6da8d75094.jpg', '2026-08-28T11:13:24+00:00', '2026-08-28T12:48:58.386228'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422549, 16443, 'BBC News', 'en', 'Norway''s King Harald dies aged 89: A beloved monarch buffeted by family crises', 'https://www.bbc.co.uk/news/articles/clykn5p5172o', 'The late king, who reigned for 35 years, broke with tradition by marrying a commoner and was widely loved by Norwegians.', 'https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/4a47/live/375be140-a2d8-11f1-aed2-8d6da8d75094.jpg', '2026-08-28T09:27:17+00:00', '2026-08-28T12:48:58.453483'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422553, 16443, 'BBC News', 'en', 'A look back at the King who broke with tradition', 'https://www.bbc.co.uk/news/videos/c93v7x5qr79o', 'Norway''s King Harald V has died aged 89 after being treated for a bacterial infection in his blood.', 'https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/d538/live/39d5abf0-a2b9-11f1-9024-715001d09aeb.jpg', '2026-08-28T09:04:11+00:00', '2026-08-28T12:48:58.507236'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422577, 16443, 'The Guardian', 'en', 'Norway’s King Harald dies aged 89', 'https://www.theguardian.com/world/2026/aug/28/norway-king-harald-dies-leaving-stormy-succession-mette-marit-crown-princesss-epstein-links', 'Monarch’s death comes at turbulent time for royal family over association of crown princess with Jeffrey Epstein King Harald V of Norway, Europe’s oldest reigning monarch, has died aged 89, the royal palace in Oslo has announced. He was succeeded immediately by his son, King Haakon VIII. “It is with deep sadness that we announce that His Majesty King Harald passed away today. King Harald passed away peacefully at Oslo University hospital on Friday 28 August at 6.35am,” the palace said in a statement. Continue reading...', 'https://i.guim.co.uk/img/media/e8b8379ac5ddd85bee997842bce3d5b24b938a74/200_96_4178_3343/master/4178.jpg?width=140&quality=85&auto=format&fit=max&s=61870803168ddb8c2ed25d0944e629c1', '2026-08-28T11:24:15+00:00', '2026-08-28T12:49:05.709352'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422620, 16443, 'Al Jazeera English', 'en', 'Norway’s King Harald V dies, succeeded by son', 'https://www.aljazeera.com/news/2026/8/28/norways-king-harald-v-dies-succeeded-by-son?traffic_source=rss', 'Harald V, who was Europe''s oldest reigning monarch, has died at the age of 89. His son will reign as King Haakon VIII.', '', '2026-08-28T08:54:14+00:00', '2026-08-28T12:49:10.621557'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422691, 16443, 'Deutsche Welle', 'en', 'Norway''s King Harald dies at 89', 'https://www.dw.com/en/norway-s-king-harald-dies-at-89/a-78524572?maca=en-rss-en-world-4025-xml-mrss', 'King Harald is succeeded by his son, who has taken the name King Haakon VIII, with Crown Princess Mette-Marit now queen.', '', '2026-08-28T08:28:00+00:00', '2026-08-28T12:49:19.787378'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422718, 16443, 'France 24', 'en', 'Uganda''s King of Tooro, once world''s youngest reigning monarch, dies at 34', 'https://www.france24.com/en/africa/20260828-uganda-s-king-of-tooro-once-world-s-youngest-reigning-monarch-dies-at-34', 'King Oyo Nyimba, leader of the Tooro kingdom in western Uganda, has died at the age of 34, the region''s prime minister of his kingdom announced Thursday. Crowned at three years old, he became the world''s youngest reigning monarch in 1995.', 'https://s.france24.com/media/display/ee60b112-a2c0-11f1-9a6d-005056a97e36/w:1024/p:16x9/AP26240259254820.jpg', '2026-08-28T09:52:44+00:00', '2026-08-28T12:49:23.798569'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422730, 16443, 'France 24', 'en', 'King Harald''s death puts focus on Norway''s future king', 'https://www.france24.com/en/king-harald-s-death-puts-focus-on-norway-s-future-king', 'Following King Harald''s death, attention is turning to Crown Prince Haakon, who is set to become Norway''s next king after a turbulent year for the royal family. His wife, Crown Princess Mette-Marit, underwent a lung transplant in June and has faced scrutiny over reported past ties to Jeffrey Epstein, while her son was sentenced to four years in prison for rape.', 'https://s.france24.com/media/display/ed97a618-a2bc-11f1-8c89-005056a97e36/w:1024/p:16x9/EN-20260828-100512-100620-CS.jpg', '2026-08-28T08:55:35+00:00', '2026-08-28T12:49:23.933115'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (422732, 16443, 'France 24', 'en', 'Norway''s King Haakon VIII, the new face of a monarchy beset by woe and scandal', 'https://www.france24.com/en/europe/20260828-norway-s-king-haakon-the-new-face-of-a-monarchy-shaken-by-scandal', 'Norway''s King Haakon VIII automatically succeeded to the throne after his father, King Harald, passed away on Friday. He is the new face of a monarchy long praised for its modernity and modesty, but in recent years it has been beset by woe and scandal, including revelations about the queen''s friendship with disgraced financier Jeffrey Epstein.', 'https://s.france24.com/media/display/9fa39668-a2c3-11f1-9f32-005056a97e36/w:1024/p:16x9/Norway.jpg', '2026-08-28T07:51:11+00:00', '2026-08-28T12:49:23.957943'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
